SESSIONS = []


def add(number, lesson, q1, q2, judge, bug, bomb, workshop, sources):
    SESSIONS.append(dict(number=number, lesson=lesson, q1=q1, q2=q2, judge=judge,
                         bug=bug, bomb=bomb, workshop=workshop, sources=sources))


